return {["scripts/items/raifu.lua"]={["Path"]="scripts/items/raifu.lua",["SHA256"]="28114a823ed99fb6dbf5fad4e72cb3246760644471aa0cdb6e6137c134bbf140",["Text"]="-----------------------------------\n-- ID: 18210\n-- Item: Raifu\n-- Additional effect: lightning damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 15 + utils.clamp(dStat / 3, 0, 18), -- 15 + 0-18% over 54 dINT, approx.\n        basePower      = math.randomInt(9, 12),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.THUNDER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/rainstorm_schema.lua"]={["Path"]="scripts/items/rainstorm_schema.lua",["SHA256"]="c4ffdaa7f07e0dbb1c651376ee2bad7ccd3b0091870a294407944230410487f8",["Text"]="-----------------------------------\n-- ID: 6050\n-- Rainstorm Schema\n-- Teaches the white magic Rainstorm\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.RAINSTORM)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.RAINSTORM)\nend\n\nreturn itemObject\n"},["scripts/items/raising_earring.lua"]={["Path"]="scripts/items/raising_earring.lua",["SHA256"]="d1885cc62700518f76bf6b9f790d35a64617d0f43aee345c831f3f00b6230bfc",["Text"]="-----------------------------------\n--  ID: 16003\n--  Reraise Earring\n--  This earring functions in the same way as the spell Reraise.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local duration = 2100\n    target:delStatusEffect(xi.effect.RERAISE)\n    target:addStatusEffect(xi.effect.RERAISE, { power = 1, duration = duration, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/rajas_ring.lua"]={["Path"]="scripts/items/rajas_ring.lua",["SHA256"]="8b70f53d7818c9bd6a9d20e408b71f0a0900eae8f49783a2692112e5785c0dce",["Text"]="-----------------------------------\n-- ID: 15543\n-- Rajas Ring\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\nend\n\nitemObject.onItemUse = function(target)\nend\n\nitemObject.onItemDrop = function(target, item, recycleBin)\n    if not recycleBin then\n        xi.mission.setVar(target, xi.mission.log_id.COP, xi.mission.id.cop.DAWN, 'Timer', 1, GetSystemTime() + 27 * 24 * 60 * 60)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/rakaznar_bolt_quiver.lua"]={["Path"]="scripts/items/rakaznar_bolt_quiver.lua",["SHA256"]="6780956d2761f5a74fc3f629f8fbf28a38f7b7fd938688dc894db1205637059a",["Text"]="-----------------------------------\n-- ID: 6281\n-- Item: Ra. Bolt Quiver\n-- When used, you will obtain one stack of Ra'Kaznar Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.RAKAZNAR_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/rakaznar_bullet_pouch.lua"]={["Path"]="scripts/items/rakaznar_bullet_pouch.lua",["SHA256"]="ee3c4c60214398c89c737daa417d46baefee85c0f5d3c388307cd37932c8dbf4",["Text"]="-----------------------------------\n-- ID: 6282\n-- Ra. Bul. Pouch\n-- When used, you will obtain one stack of Ra'Kaznar Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.RAKAZNAR_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/rakaznar_quiver.lua"]={["Path"]="scripts/items/rakaznar_quiver.lua",["SHA256"]="0aa5c4cf6467203ef22b270736d8f5a852a6bbe8e3ca60b54dcf7e6e3c88b721",["Text"]="-----------------------------------\n-- ID: 6280\n-- Ra'Kaznar Quiver\n-- When used, you will obtain one stack of Ra'Kaznar Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.RAKAZNAR_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/ram_staff.lua"]={["Path"]="scripts/items/ram_staff.lua",["SHA256"]="3725d75042079bac2eae5a283c51b4cde47ea35a7649912f8342414fead97b38",["Text"]="-----------------------------------\n-- ID: 18612\n-- Ram Staff\n-- Enchantment: \"Retrace\" (Southern San d'Oria[S])\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.SOUTHERN_SAN_DORIA_S, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/ramblers_cloak.lua"]={["Path"]="scripts/items/ramblers_cloak.lua",["SHA256"]="9fa7c47c880b3a74d861bf3d95e1cd14adcc3a8a2aa43636181f52355eac0935",["Text"]="-----------------------------------\n-- ID: 11312\n-- Equip: Ramblers Cloak\n--  Latent effect: STR +5\n-- Active when TP >= 100%, should not active during weapon skills\n-- Note: Script is not working 100%, there is no check on equipment after it has been equipped or unequipped.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\nend\n\nreturn itemObject\n"},["scripts/items/ramuhs_staff.lua"]={["Path"]="scripts/items/ramuhs_staff.lua",["SHA256"]="234df8301e31a4ab8304f624839c704a2ee4e5faf6f6cd78c9a8a86078354bef",["Text"]="-----------------------------------\n-- ID: 17531\n-- Item: Ramuh's Staff\n-- Additional effect: lightning damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local chance = 3 -- TODO: check scaling on non-lightningday\n\n    if VanadielDayOfTheWeek() == xi.day.LIGHTNINGDAY then\n        chance = xi.additionalEffect.linearProcRate(dStat, 140, 15, 50) -- Numbers are smoothed out a bit. Scale from 15% at dINT 0 to 50% at +140 DINT\n    end\n\n    local pTable =\n    {\n        chance         = chance,\n        basePower      = math.randomInt(18, 25),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.THUNDER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/random_ring.lua"]={["Path"]="scripts/items/random_ring.lua",["SHA256"]="97ce211652b4d5f72b73c392b3ea78bf5ef854522b7e6f18276c9660c7eb72b8",["Text"]="-----------------------------------\n-- ID: 15770\n-- Item: Random Ring\n-- Item Effect: Enchantment Dex + math.randomInt(1, 8)\n-- Duration: 30 Mins\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.RANDOM_RING) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.RANDOM_RING)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.RANDOM_RING) then\n        local power = math.randomInt(1, 8)\n\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { power = power, duration = 3600, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.RANDOM_RING })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, effect:getPower())\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/ranger_die.lua"]={["Path"]="scripts/items/ranger_die.lua",["SHA256"]="630af388d2249c8a453a36842401f64a187ff75f1f7a9f633e2139855cc3bf24",["Text"]="-----------------------------------\n-- ID: 5487\n-- Ranger Die\n-- Teaches the job ability Hunter's Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.HUNTERS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.HUNTERS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/raphaels_rod.lua"]={["Path"]="scripts/items/raphaels_rod.lua",["SHA256"]="daa4033c56b92fd00612c61b2b0e15216536dce505865a1a61e53d73eb0619a5",["Text"]="-----------------------------------\n-- ID: 18398\n-- Raphael's Rod\n-- Grants Reraise III.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:delStatusEffect(xi.effect.RERAISE)\n    target:addStatusEffect(xi.effect.RERAISE, { power = 3, duration = 7200, origin = user })\n    target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.RERAISE)\nend\n\nreturn itemObject\n"},["scripts/items/rarab_meatball.lua"]={["Path"]="scripts/items/rarab_meatball.lua",["SHA256"]="bd7e0ba937c03a305448e410f5cd4575c34c66e40d854c1dfea28c89fec5260e",["Text"]="-----------------------------------\n-- ID: 4507\n-- Item: rarab_meatball\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Health 10\n-- Strength 2\n-- Vitality 2\n-- Intelligence -1\n-- Attack % 30\n-- Attack Cap 20\n-- Ranged ATT % 30\n-- Ranged ATT Cap 20\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.STR, 2)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.INT, -1)\n    effect:addMod(xi.mod.FOOD_ATTP, 30)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 20)\n    effect:addMod(xi.mod.FOOD_RATTP, 30)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 20)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/rarab_tail.lua"]={["Path"]="scripts/items/rarab_tail.lua",["SHA256"]="9e9ee47c24a5d708bb55d558fad224a1545db963cb4dce4b357c165d58d04c14",["Text"]="-----------------------------------\n-- ID: 4444\n-- Item: rarab_tail\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility 1\n-- Vitality -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.VIT, -3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/rebirth_feather.lua"]={["Path"]="scripts/items/rebirth_feather.lua",["SHA256"]="ec6956fa7875c58ed662b48afc808ee6902ec712adbf941b4d2fe5c46f597b97",["Text"]="-----------------------------------\n-- ID: 5259\n-- Item: Rebirth Feather\n-- Status Effect: Reraise II\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local duration = 28800 -- 8 hours\n    target:delStatusEffect(xi.effect.RERAISE)\n    -- Test EXP\n    -- * No Raise        - 26740 -> 25114 = 1626 lost\n    -- * Rebirth Feather - 25114 -> 24707 = 407 lost (25%)\n    target:addStatusEffect(xi.effect.RERAISE, { power = 2, duration = duration, origin = user })\n    target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.RERAISE)\nend\n\nreturn itemObject\n"},["scripts/items/recall_ring_jugner.lua"]={["Path"]="scripts/items/recall_ring_jugner.lua",["SHA256"]="15b781befb11cd3662ab2bac7c86332f206bce3ba3339f0261657da6c7fdebf6",["Text"]="-----------------------------------\n-- ID: 15841\n-- Recall ring: Jugner\n-- Enchantment: \"Recall-Jugner\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasKeyItem(xi.keyItem.JUGNER_GATE_CRYSTAL) then\n        result = 445\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.JUGNER, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/recall_ring_meriphataud.lua"]={["Path"]="scripts/items/recall_ring_meriphataud.lua",["SHA256"]="d5eb2e6cc791453caee185ff248685d84ab33687ed3ee01e4aa56b841d055910",["Text"]="-----------------------------------\n-- ID: 15843\n-- Recall ring: Meriphataud\n-- Enchantment: \"Recall-Meriphataud\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasKeyItem(xi.keyItem.MERIPHATAUD_GATE_CRYSTAL) then\n        result = 445\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.MERIPH, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/recall_ring_pashhow.lua"]={["Path"]="scripts/items/recall_ring_pashhow.lua",["SHA256"]="fcc23f6026564f55d743e6a9f9d53016194711f985d1ae49f0fdafc8c30ae14c",["Text"]="-----------------------------------\n-- ID: 15842\n-- Recall ring: Pashhow\n-- Enchantment: \"Recall-Pashhow\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasKeyItem(xi.keyItem.PASHHOW_GATE_CRYSTAL) then\n        result = 445\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.PASHH, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/red_bubble-eye.lua"]={["Path"]="scripts/items/red_bubble-eye.lua",["SHA256"]="a98f5f8adbd33e20508c162c4b000994668be231ed00f4d75f3210d2f2640e85",["Text"]="-----------------------------------\n-- ID: 5446\n-- Item: Red Bubble-Eye\n-- Food Effect: 5 Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/red_curry_bun.lua"]={["Path"]="scripts/items/red_curry_bun.lua",["SHA256"]="9d906d59ca5f065aeef12eb7209369490b1f4dc71aa22cae305aaf3086d53b84",["Text"]="-----------------------------------\n-- ID: 5759\n-- Item: red_curry_bun\n-- Food Effect: 30 Min, All Races\n-- https://wiki.ffo.jp/html/17770.html\n-----------------------------------\n-- Health 25\n-- Strength 7\n-- Agility 1\n-- Intelligence -2\n-- Attack % 23 (cap 150)\n-- Ranged Atk % 23 (cap 150)\n-- Demon Killer 4\n-- Resist Sleep +3\n-- HP recovered when healing +2\n-- MP recovered when healing +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nlocal dataTable =\n{\n    [ 1] = { xi.mod.FOOD_HP,        35,  30,  25 },\n    [ 2] = { xi.mod.STR,             7,   7,   7 },\n    [ 3] = { xi.mod.AGI,             3,   2,   1 },\n    [ 4] = { xi.mod.INT,             0,  -1,  -2 },\n    [ 5] = { xi.mod.HPHEAL,          6,   4,   2 },\n    [ 6] = { xi.mod.MPHEAL,          3,   2,   1 },\n    [ 7] = { xi.mod.FOOD_ATTP,      25,  24,  23 },\n    [ 8] = { xi.mod.FOOD_ATT_CAP,  150, 150, 150 },\n    [ 9] = { xi.mod.FOOD_RATTP,     25,  24,  23 },\n    [10] = { xi.mod.FOOD_RATT_CAP, 150, 150, 150 },\n    [11] = { xi.mod.DEMON_KILLER,    5,   4,   4 },\n    [12] = { xi.mod.SLEEPRES,        5,   3,   3 }\n}\n\nitemObject.onEffectGain = function(target, effect)\n    for i = 1, #dataTable do\n        -- Get party factor.\n        local partySize = target:getPartySize()\n        local column = 4\n        if partySize >= 4 then\n            column = 2\n        elseif partySize >= 2 then\n            column = 3\n        end\n\n        effect:addMod(dataTable[i][1], dataTable[i][column])\n    end\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/red_curry_bun_+1.lua"]={["Path"]="scripts/items/red_curry_bun_+1.lua",["SHA256"]="dd7530ce9e1128c2c7afa001e219fe94a23ad8485bd8fb72140fba276d61aa22",["Text"]="-----------------------------------\n-- ID: 5765\n-- Item: red_curry_bun_+1\n-- Food Effect: 60 Min, All Races\n-----------------------------------\n-- TODO: Group effects\n-- Health 35\n-- Strength 7\n-- Agility 3\n-- Attack % 25 (cap 150)\n-- Ranged Atk % 25 (cap 150)\n-- Demon Killer 6\n-- Resist Sleep +5\n-- HP recovered when healing +6\n-- MP recovered when healing +3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 35)\n    effect:addMod(xi.mod.STR, 7)\n    effect:addMod(xi.mod.AGI, 3)\n    effect:addMod(xi.mod.FOOD_ATTP, 25)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 150)\n    effect:addMod(xi.mod.FOOD_RATTP, 25)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 150)\n    effect:addMod(xi.mod.DEMON_KILLER, 6)\n    effect:addMod(xi.mod.SLEEPRES, 5)\n    effect:addMod(xi.mod.HPHEAL, 6)\n    effect:addMod(xi.mod.MPHEAL, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/red_drop.lua"]={["Path"]="scripts/items/red_drop.lua",["SHA256"]="9f412d92d2b16ae22e61b1bfcc04ccdc989632dd8ec5259aae29950b2acf9125",["Text"]="-----------------------------------\n--  ID: 4258\n--  Item: Red Drop\n--  Strength 5\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.STR_BOOST, { power = 5, duration = 900, origin = user })\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/red_hot_cracker.lua"]={["Path"]="scripts/items/red_hot_cracker.lua",["SHA256"]="98e4c4c4c1b244c22f4324491ef0a408480606c1788cf3b07a1a5248b6e61a7e",["Text"]="-----------------------------------\n-- ID: 4281\n-- Item: red_hot_cracker\n-- Food Effect: 3Min, All Races\n-----------------------------------\n-- HP Recovered While Healing 9\n-- Beast Killer 12\n-- Resist Sleep 12\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HPHEAL, 9)\n    effect:addMod(xi.mod.BEAST_KILLER, 12)\n    effect:addMod(xi.mod.SLEEPRES, 12)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/red_mage_die.lua"]={["Path"]="scripts/items/red_mage_die.lua",["SHA256"]="5fa787e2e05a8074306b135d4d3f610cb49ce3098215b3ca3b8aaab426b046b4",["Text"]="-----------------------------------\n-- ID: 5481\n-- Red Mage Die\n-- Teaches the job ability Warlock's Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.WARLOCKS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.WARLOCKS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/red_terrapin.lua"]={["Path"]="scripts/items/red_terrapin.lua",["SHA256"]="f141c12ea07557ef48fab1e31cc409cd1e8d6bb22aaad6a8ecbd021759ffdc49",["Text"]="-----------------------------------\n-- ID: 4402\n-- Item: red_terrapin\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 3\n-- Mind -5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.MND, -5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/redeyes.lua"]={["Path"]="scripts/items/redeyes.lua",["SHA256"]="41c3e8c8227c0f3e9e3121ae32b16dbaead2c2ea5b3bd3dd2d5ab462fcb15fac",["Text"]="-----------------------------------\n-- ID: 16120\n-- redeyes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ANGELWING, 99 } }) -- Angelwing x99\nend\n\nreturn itemObject\n"},["scripts/items/refined_chair_set.lua"]={["Path"]="scripts/items/refined_chair_set.lua",["SHA256"]="656815777bf68cead6b63470317259ad60966d4e8484fc9950f6c8438783fced",["Text"]="-----------------------------------\n-- ID: 6380\n-- Item: Refined Chair\n-- Item Effect: Grant Refined chair key item\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nlocal keyItemId = xi.keyItem.REFINED_CHAIR\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasKeyItem(keyItemId) then\n        return xi.msg.basic.ALREADY_HAVE_KEY_ITEM, 0, keyItemId\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addKeyItem(keyItemId)\n    target:messageBasic(xi.msg.basic.OBTAINED_KEY_ITEM, 6380, keyItemId)\nend\n\nreturn itemObject\n"},["scripts/items/regain_feather.lua"]={["Path"]="scripts/items/regain_feather.lua",["SHA256"]="0d2e5bd9e7cdb4e77d42ea5ef8c4eda0dc5b433267b6656c9de24f55a17953d8",["Text"]="-----------------------------------\n-- ID: 5260\n-- Item: Regain Feather\n-- Status Effect: Medicated, 2 hours\n-- Instantly restors HP/MP full TP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:setHP(target:getMaxHP())\n    target:setMP(target:getMaxMP())\n    target:setTP(3000)\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 7200, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/regen_collar.lua"]={["Path"]="scripts/items/regen_collar.lua",["SHA256"]="9a845b33e412447cf7bca98d01358d616d3ef54cddd68a830fbebc0d82b7be38",["Text"]="-----------------------------------\n-- ID: 15526\n-- Item: Regen Collar\n-- Item Effect: Restores 40 HP over 120 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.REGEN_COLLAR)\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.REGEN_COLLAR) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 120, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.REGEN_COLLAR })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.REGEN, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/regen_cuirass.lua"]={["Path"]="scripts/items/regen_cuirass.lua",["SHA256"]="c22012bfad19c09628e62f01f39064a9b32c2cbb127b9e252f7d4345288d82c4",["Text"]="-----------------------------------\n-- ID: 15170\n-- Item: regen cuirass\n-- Item Effect: gives regen\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.REGEN_CUIRASS) then\n        if target:hasStatusEffect(xi.effect.REGEN) then\n            target:messageBasic(xi.msg.basic.NO_EFFECT)\n        else\n            target:addStatusEffect(xi.effect.REGEN, { power = 15, duration = 180, origin = user, tick = 3, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.REGEN_CUIRASS })\n        end\n    end\nend\n\nreturn itemObject\n"},["scripts/items/regiment_kheten.lua"]={["Path"]="scripts/items/regiment_kheten.lua",["SHA256"]="a3f72e0133a3ff9242d83ce5d912189c6df278acc2f5a01313460f753b7d280b",["Text"]="-----------------------------------\n-- ID: 18493\n-- Item: Regiment Kheten\n-- Item Effect: TP +10\n-- Durration: Instant\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addTP(100)\nend\n\nreturn itemObject\n"},["scripts/items/reishi_mushroom.lua"]={["Path"]="scripts/items/reishi_mushroom.lua",["SHA256"]="863992c57280471b9912ecd3628ca49c55ad6b32f8f58c2d521a13c81f47d236",["Text"]="-----------------------------------\n-- ID: 4449\n-- Item: reishi_mushroom\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Strength -6\n-- Mind 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, -6)\n    effect:addMod(xi.mod.MND, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/remedy.lua"]={["Path"]="scripts/items/remedy.lua",["SHA256"]="1a173420605a240c518c3212605abe758b9cf1ded6f0fa124ef1e034c0a2caf7",["Text"]="-----------------------------------\n-- ID: 4155\n-- Item: Remedy\n-- Item Effect: This potion remedies status ailments.\n-- Works on paralysis, silence, blindness, poison, and disease.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nlocal removableStatus =\n{\n    xi.effect.SILENCE,\n    xi.effect.BLINDNESS,\n    xi.effect.POISON,\n    xi.effect.PARALYSIS,\n}\n\nitemObject.onItemUse = function(target)\n    for _, effectId in ipairs(removableStatus) do\n        if target:hasStatusEffect(effectId) then\n            target:delStatusEffect(effectId)\n        end\n    end\n\n    local rDisease = math.randomInt(1, 2) -- Disease is not guaranteed to be cured, 1 means removed 2 means fail. 50% chance\n    if rDisease == 1 and target:hasStatusEffect(xi.effect.DISEASE) then\n        target:delStatusEffect(xi.effect.DISEASE)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/rengedama.lua"]={["Path"]="scripts/items/rengedama.lua",["SHA256"]="33b3ec93d6c577ac97bef99fe6a381a992837d02b1178194d7f70b5d63626591",["Text"]="-----------------------------------\n-- ID: 5884\n-- Item: Rengedama\n-- Effect: Far East Firework\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/reppu.lua"]={["Path"]="scripts/items/reppu.lua",["SHA256"]="a055ca91fe715b37908a9b6e5d23c52d734dc49442b5cd9572f2f72b2348055e",["Text"]="-----------------------------------\n-- ID: 17782\n-- Item: Reppu\n-- Additional effect: wind damage depending on ammo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local damageRange = xi.additionalEffect.getConsumableAmmoItemDamageRange(xi.element.WIND, actor:getEquipID(xi.slot.AMMO))\n\n    if not damageRange then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance          = 15, -- TODO: guessed based on rapier/sword proc rates\n        basePower       = math.randomInt(damageRange[1], damageRange[2]),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.WIND,\n        canMAB          = false,\n        canResist       = true,\n        lowestResist    = 0.5,\n        useAmmo         = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/reppu_+1.lua"]={["Path"]="scripts/items/reppu_+1.lua",["SHA256"]="a5e50162260a86cbfb0320ad2d623f1517404858fa9efffd2dbda142b707c834",["Text"]="-----------------------------------\n-- ID: 17783\n-- Item: Reppu +1\n-- Additional effect: wind damage depending on ammo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local damageRange = xi.additionalEffect.getConsumableAmmoItemDamageRange(xi.element.WIND, actor:getEquipID(xi.slot.AMMO))\n\n    if not damageRange then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance          = 15, -- TODO: guessed based on rapier/sword proc rates\n        basePower       = math.randomInt(damageRange[1], damageRange[2]),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.WIND,\n        canMAB          = false,\n        canResist       = true,\n        lowestResist    = 0.5,\n        useAmmo         = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/republic_earring.lua"]={["Path"]="scripts/items/republic_earring.lua",["SHA256"]="0f1b6e43227f7de0048296d51d66b10121768533a35f545b5c802914b60f96ae",["Text"]="-----------------------------------\n-- ID: 16039\n-- Republic Earring\n-- Enchantment: \"Teleport\" (Bastok Markets)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.REPUBLIC_EARRING, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/republic_signet_staff.lua"]={["Path"]="scripts/items/republic_signet_staff.lua",["SHA256"]="1d754f54b87b605936670ef9e35563913f11fb259503bf011f8a2d75698792e2",["Text"]="-----------------------------------\n-- ID: 17583\n-- Item: Republic Signet Staff\n-- Effect: Signet\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getNation() ~= xi.nation.BASTOK then\n        return xi.msg.basic.ITEM_CANNOT_USE_ON\n    end\n\n    -- If target's current region is not a conquest region or not a nation city involved with conquest\n    if target:getCurrentRegion() > xi.region.JEUNO then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    -- Can only use on targets within party or self\n    if target:getID() ~= caster:getID() then\n        if\n        caster:getPartyLeader() == nil or\n            target:getPartyLeader():getID() ~= caster:getPartyLeader():getID()\n        then\n            return xi.msg.basic.ITEM_CANNOT_USE_ON\n        end\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:delStatusEffectsByFlag(xi.effectFlag.INFLUENCE, true)\n    target:addStatusEffect(xi.effect.SIGNET, { duration = 18000, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/republic_stables_medal.lua"]={["Path"]="scripts/items/republic_stables_medal.lua",["SHA256"]="cf7bd2d628f14f13e9498c053b9962b25f8c6264d9cf7bb0d85e44f447e0fb87",["Text"]="-----------------------------------\n-- ID: 13180\n-- Item: Republic Stables Medal\n-- Teleports to Chocobo Stables (Bastok)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasVisitedZone(xi.zone.BASTOK_MINES) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.CHOCO_BASTOK, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/reraise_earring.lua"]={["Path"]="scripts/items/reraise_earring.lua",["SHA256"]="8bef9d1f21faf41874b06d88815a9f472c6611f2c0d455b4a0b1f0db0b3aa6d6",["Text"]="-----------------------------------\n-- ID: 14790\n-- Reraise Earring\n--  This earring functions in the same way as the spell Reraise.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local duration = 7200\n    target:delStatusEffect(xi.effect.RERAISE)\n    target:addStatusEffect(xi.effect.RERAISE, { power = 1, duration = duration, origin = user })\n    target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.RERAISE)\nend\n\nreturn itemObject\n"},["scripts/items/reraise_gorget.lua"]={["Path"]="scripts/items/reraise_gorget.lua",["SHA256"]="5f1d69390261b44f65216272e50de83de2a4127270124b85033f66bf3a6a43e4",["Text"]="-----------------------------------\n-- ID: 13171\n-- Reraise Gorget\n--  This necklace functions in the same way as the spell Reraise II.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local duration = 7200\n    target:delStatusEffect(xi.effect.RERAISE)\n    target:addStatusEffect(xi.effect.RERAISE, { power = 2, duration = duration, origin = user })\n    target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.RERAISE)\nend\n\nreturn itemObject\n"},["scripts/items/reraise_hairpin.lua"]={["Path"]="scripts/items/reraise_hairpin.lua",["SHA256"]="30b1ce4775073d84215e86b2fd604786a9309ae59c5e873a9abba24c75b1c128",["Text"]="-----------------------------------\n-- ID: 15211\n-- Reraise Hairpin\n--  This Hairpin functions in the same way as the spell Reraise II.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local duration = 7200\n    target:delStatusEffect(xi.effect.RERAISE)\n    target:addStatusEffect(xi.effect.RERAISE, { power = 2, duration = duration, origin = user })\n    target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.RERAISE)\nend\n\nreturn itemObject\n"},["scripts/items/reraiser.lua"]={["Path"]="scripts/items/reraiser.lua",["SHA256"]="1315693e59f2d5084198317a1f291f1c1f590fdf6a515cfa4761d8855885ec18",["Text"]="-----------------------------------\n-- ID: 4172\n-- Item: Reraiser\n-- Item Effect: This potion functions inthe same way as the spell Reraise.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local duration = 3600\n    target:delStatusEffect(xi.effect.RERAISE)\n    target:addStatusEffect(xi.effect.RERAISE, { power = 1, duration = duration, origin = user })\n    target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.RERAISE)\nend\n\nreturn itemObject\n"},["scripts/items/resolution_ring.lua"]={["Path"]="scripts/items/resolution_ring.lua",["SHA256"]="5d862e28c4d88b06877611d3b8e9e8732d34b5b1611593cbaf48baa1ae4ae3f5",["Text"]="-----------------------------------\n-- ID: 28568\n-- Item: Resolution Ring\n-- Experience point bonus\n-----------------------------------\n-- Bonus: +50%\n-- Duration: 720 min\n-- Max bonus: 30000 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.DEDICATION) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.DEDICATION\n    local power     = 50\n    local duration  = 43200\n    local subpower  = 30000\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/return_ring.lua"]={["Path"]="scripts/items/return_ring.lua",["SHA256"]="dac04e705b72df54b14625392e4068b776e12e27b01a1b1089ec24ad7b307155",["Text"]="-----------------------------------\n-- ID: 15542\n-- Teleport Return Ring\n-- Enchantment: \"Outpost Warp\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    local region = target:getCurrentRegion()\n\n    if\n        not xi.conquest.canTeleportToOutpost(target, region) or\n        GetRegionOwner(region) ~= target:getNation()\n    then\n        result = xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    local region = target:getCurrentRegion()\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.OUTPOST, duration = 4, origin = user, icon = 0, subPower = region })\nend\n\nreturn itemObject\n"},["scripts/items/revilers_helm.lua"]={["Path"]="scripts/items/revilers_helm.lua",["SHA256"]="70c402df08952f77854bb40da74966de8dd45292a522d96e15829d9f53ef8f58",["Text"]="-----------------------------------\n-- ID: 15175\n-- Item: Reviler's Helm\n-- Enchantment: Provoke\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:isMob() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    -- Grants the same enmity as Provoke (CE 1, VE 1800)\n    target:addEnmity(user, 1, 1800)\n    target:updateClaim(user)\nend\n\nreturn itemObject\n"},["scripts/items/revitalizer.lua"]={["Path"]="scripts/items/revitalizer.lua",["SHA256"]="361f7a56949b3732d0a12da4e849d45f0fe44f95a85657e985bac4ed1d037ec2",["Text"]="-----------------------------------\n-- ID: 4157\n-- Item: Revitalizer\n-- Item Effect: Resets all Job Ability Timers\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:resetRecasts()\n    target:messageBasic(xi.msg.basic.ALL_ABILITIES_RECHARGED, 0)\nend\n\nreturn itemObject\n"},["scripts/items/revive_feather.lua"]={["Path"]="scripts/items/revive_feather.lua",["SHA256"]="f556c6ae8684c3e57b7f27e9a84be415dffd44ecd2ac95b04105c08d7d4fb3ee",["Text"]="-----------------------------------\n-- ID: 5258\n-- Item: Revive Feather\n-- Status Effect: Reraise\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local duration = 28800 -- 8 hours\n    target:delStatusEffect(xi.effect.RERAISE)\n    -- Test EXP\n    -- * No Raise       - 26740 -> 25114 = 1626 lost\n    -- * Revive Feather - 27553 -> 26740 = 813 lost (50%)\n    target:addStatusEffect(xi.effect.RERAISE, { power = 1, duration = duration, origin = user })\n    target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.RERAISE)\nend\n\nreturn itemObject\n"},["scripts/items/rice_ball.lua"]={["Path"]="scripts/items/rice_ball.lua",["SHA256"]="4c53b584e9b3e843c5b82e61fd61fefbc6899bb0c25f144e2f8b530c4e6b3c8b",["Text"]="-----------------------------------\n-- ID: 4405\n-- Item: Rice Ball\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- HP 10,\n-- Vit +2\n-- Dex -1\n-- hHP +1\n-- Effect with enhancing equipment (Note: these are latents on gear with the effect)\n-- Def +50\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.DEX, -1)\n    effect:addMod(xi.mod.HPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/rice_dumpling.lua"]={["Path"]="scripts/items/rice_dumpling.lua",["SHA256"]="fd6b96de583a7a1cd0c9507c6d6f978b53a628eabe16e1bb51db6708c6b5e40d",["Text"]="-----------------------------------\n-- ID: 4271\n-- Item: rice_dumpling\n-- Food Effect: 30minutes, All Races\n-----------------------------------\n-- HP 17\n-- Strength 3\n-- Vitality 2\n-- Agility 1\n-- Attack 20% (caps @ 45)\n-- Ranged Attack 30% (caps @ 45)\n-- HP Regeneration While Healing 2\n-- MP Regeneration While Healing 2\n-- Accuracy 5\n-- Resist Paralyze +4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 17)\n    effect:addMod(xi.mod.STR, 3)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.FOOD_ATTP, 20)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 45)\n    effect:addMod(xi.mod.FOOD_RATTP, 30)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 45)\n    effect:addMod(xi.mod.HPHEAL, 2)\n    effect:addMod(xi.mod.MPHEAL, 2)\n    effect:addMod(xi.mod.ACC, 5)\n    effect:addMod(xi.mod.PARALYZERES, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/righteous_bolt.lua"]={["Path"]="scripts/items/righteous_bolt.lua",["SHA256"]="033e956118227dd95aa781aad855e904b4e117eed21dedd73ad328dbabb16ca6",["Text"]="-----------------------------------\n-- ID: 21315\n-- Item: Righteous Bolt\n-- Additional effect: Light damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.MND)\n    -- Unconfirmed power.\n\n    local pTable =\n    {\n        ignoreEnSpell   = true,\n        basePower       = 40 + utils.clamp(dStat, -3, 8) + utils.clamp(math.floor((dStat - 8) / 2), 0, 8),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.LIGHT,\n        canResist       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/righteous_bolt_quiver.lua"]={["Path"]="scripts/items/righteous_bolt_quiver.lua",["SHA256"]="8c81f1110b3a070bfb926d6e7c3eff4531fc8e1becaaeb3a93646c4aca91d6bb",["Text"]="-----------------------------------\n-- ID: 6279\n-- Item: Rig. Bolt Quiver\n-- When used, you will obtain one stack of Righteous Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.RIGHTEOUS_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/ritterhentzes.lua"]={["Path"]="scripts/items/ritterhentzes.lua",["SHA256"]="cc58c57e4c8b3bb84bff4fdf57c043f99e6c45bf66e1230833f9608e272ff4d9",["Text"]="-----------------------------------\n-- ID: 15652\n-- Item: ritter\n-- Item Effect: Blaze Spikes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.BLAZE_SPIKES, { power = 20, duration = 210, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/river_top_+1.lua"]={["Path"]="scripts/items/river_top_+1.lua",["SHA256"]="fc2fca4406d2887968ef580c36c612d89d80f6b1d0a20daa9c3554d5f7db23c3",["Text"]="-----------------------------------\n-- ID: 10270\n-- River Top +1\n-- Dispense: Berry Snowcone\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BERRY_SNOW_CONE, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/roast_carp.lua"]={["Path"]="scripts/items/roast_carp.lua",["SHA256"]="7778b978b1c04e28aa93f69dd9cbd4407235846691bf76016fb7b1a12e2dd06b",["Text"]="-----------------------------------\n-- ID: 4537\n-- Item: roast_carp\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Dexterity 1\n-- Mind -1\n-- Ranged ATT % 14 (cap 40)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.MND, -1)\n    effect:addMod(xi.mod.FOOD_RATTP, 14)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 40)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/roast_mushroom.lua"]={["Path"]="scripts/items/roast_mushroom.lua",["SHA256"]="6d1e24257a072b24da7c78e6d643b997fa011280bcd909a00415ad7088dc845e",["Text"]="-----------------------------------\n-- ID: 4410\n-- Item: roast_mushroom\n-- Food Effect: 30minutes, All Races\n-----------------------------------\n-- Magic Points 10\n-- Strength -1\n-- Mind 3\n-- Enmity -1\n-- MP Recovered While Healing 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 10)\n    effect:addMod(xi.mod.STR, -1)\n    effect:addMod(xi.mod.MND, 3)\n    effect:addMod(xi.mod.ENMITY, -1)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/roast_pipira.lua"]={["Path"]="scripts/items/roast_pipira.lua",["SHA256"]="819a9245cc4b921ecf853f6bf5fccdadc7aef99a208de42cc42f84d6cb1062a7",["Text"]="-----------------------------------\n-- ID: 4538\n-- Item: roast_pipira\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Dexterity 3\n-- Mind -1\n-- Attack % 14\n-- Attack Cap 75\n-- Ranged ATT % 14\n-- Ranged ATT Cap 75\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.MND, -1)\n    effect:addMod(xi.mod.FOOD_ATTP, 14)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 75)\n    effect:addMod(xi.mod.FOOD_RATTP, 14)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 75)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/roast_trout.lua"]={["Path"]="scripts/items/roast_trout.lua",["SHA256"]="cf0324f5513a96adf0f55df9e6548b950652c8097a975352dff4739fe9bb3d0e",["Text"]="-----------------------------------\n-- ID: 4404\n-- Item: roast_trout\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Dexterity 3\n-- Mind -1\n-- Ranged ATT % 14 (cap 50)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.MND, -1)\n    effect:addMod(xi.mod.FOOD_RATTP, 14)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 50)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/roast_turkey.lua"]={["Path"]="scripts/items/roast_turkey.lua",["SHA256"]="769da447c85b946f1c5b550df57a30c5536160e75e178db020e6d98df3902c9d",["Text"]="-----------------------------------\n-- ID: 5620\n-- Item: roast_turkey\n-- Food Effect: 240Min, All Races\n-----------------------------------\n-- Strength 4\n-- Vitality 4\n-- hMP +2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 4)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.HPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/rogue_rice_ball.lua"]={["Path"]="scripts/items/rogue_rice_ball.lua",["SHA256"]="f9cc12de5920598670ee329fc50c5568d0d1e749f3c5cdb560b9e2cca037c812",["Text"]="-----------------------------------\n-- ID: 4604\n-- Item: Rogue Rice Ball\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- HP +12\n-- Vit +3\n-- hHP +2\n-- Effect with enhancing equipment (Note: these are latents on gear with the effect)\n-- Def +50\n-- Beast Killer +4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 12)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.HPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/rolanberry.lua"]={["Path"]="scripts/items/rolanberry.lua",["SHA256"]="ad7eb9782c4ed1cb36e789285d7227915b0a282ffdc4725f8ba6970aafb4be4c",["Text"]="-----------------------------------\n-- ID: 4365\n-- Item: rolanberry\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility -4\n-- Intelligence 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, -4)\n    effect:addMod(xi.mod.INT, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/rolanberry_864_c.e..lua"]={["Path"]="scripts/items/rolanberry_864_c.e..lua",["SHA256"]="175bf78e336a802d7fbeffdee471afacb542d60bd24c57021189f2b82177eb0c",["Text"]="-----------------------------------\n-- ID: 4531\n-- Item: rolanberry_864_ce)\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility -3\n-- Intelligence 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, -3)\n    effect:addMod(xi.mod.INT, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/rolanberry_874_c.e..lua"]={["Path"]="scripts/items/rolanberry_874_c.e..lua",["SHA256"]="bbc3241751ba96fd01bc86246ccba6c9d518ea395919707d25b54378f4ee3d55",["Text"]="-----------------------------------\n-- ID: 4530\n-- Item: rolanberry_874_ce)\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility -3\n-- Intelligence 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, -3)\n    effect:addMod(xi.mod.INT, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"}};
